const response = $input.first().json;
  const originalData = $node['提取参数'].json;
  let content = response?.choices?.[0]?.message?.content;
  if (typeof content !== 'string') {
    throw new Error('模型未返回商品元数据');
  }

  content = content.replace(/```json\s*/gi, '').replace(/```/g, '').trim();
  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (error) {
    throw new Error('商品元数据不是合法 JSON 对象');
  }

  if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') {
    throw new Error('商品元数据必须为 JSON 对象');
  }
  if (!Array.isArray(parsed.products) || parsed.products.length !== originalData.subTasks.length) {
    throw new Error(`products 数量不匹配: ${Array.isArray(parsed.products) ? parsed.products.length : 0} / ${originalData.subTasks.length}`);
  }

  const productMap = new Map(parsed.products.map(item => [String(item?.sub_task_id || ''), item]));
  if (productMap.size !== originalData.subTasks.length) {
    throw new Error('products 中的 sub_task_id 缺失或重复');
  }
  const products = originalData.subTasks.map((subTask, index) => {
    const item = productMap.get(subTask.sub_task_id);
    if (!item) {
      throw new Error(`缺少 sub_task_id: ${subTask.sub_task_id}`);
    }
    const productName = String(item.product_name || '').replace(/\s+/g, ' ').trim();
    const productDescription = String(item.product_description || '').replace(/\s+/g, ' ').trim();
    if (productName.length < 10 || productName.length > 120) {
      throw new Error(`商品标题#${index + 1}长度必须为10~120字符`);
    }
    if (productDescription.length < 100 || productDescription.length > 3000) {
      throw new Error(`商品描述#${index + 1}长度必须为100~3000字符`);
    }
    return {
      sub_task_id: subTask.sub_task_id,
      product_name: productName,
      product_description: productDescription,
    };
  });
  if (new Set(products.map(item => item.product_name.toLocaleLowerCase('vi'))).size !== products.length) {
    throw new Error('商品标题存在重复项');
  }

  let variationLabels = { name1: '', name2: '', values: [] };
  if (originalData.productType !== 'single') {
    const labels = parsed.variation_labels;
    if (!labels || !Array.isArray(labels.values) || labels.values.length !== originalData.variants.length) {
      throw new Error('variation_labels 数量不匹配');
    }
    const name1 = String(labels.name1 || '').trim();
    const name2 = String(labels.name2 || '').trim();
    if (!name1 || name1.length > 14) {
      throw new Error('一级规格名必须为1~14字符');
    }
    if (originalData.productType === 'two' && (!name2 || name2.length > 14)) {
      throw new Error('二级规格名必须为1~14字符');
    }
    const labelMap = new Map(labels.values.map(item => [String(item?.id || ''), item]));
    if (labelMap.size !== originalData.variants.length) {
      throw new Error('variation_labels 中的 id 缺失或重复');
    }
    const translatedPrimary = new Map();
    const combinations = new Set();
    const values = originalData.variants.map(source => {
      const item = labelMap.get(source.id);
      if (!item) {
        throw new Error(`缺少规格 ID: ${source.id}`);
      }
      const option1 = String(item.option1 || '').trim();
      const option2 = String(item.option2 || '').trim();
      if (!option1 || option1.length > 20) {
        throw new Error(`规格 ${source.id} 的 option1 必须为1~20字符`);
      }
      if (originalData.productType === 'two' && (!option2 || option2.length > 20)) {
        throw new Error(`规格 ${source.id} 的 option2 必须为1~20字符`);
      }
      const sourceKey = source.option1.toLocaleLowerCase('vi');
      const translatedKey = option1.toLocaleLowerCase('vi');
      if (translatedPrimary.has(sourceKey) && translatedPrimary.get(sourceKey) !== translatedKey) {
        throw new Error(`一级规格 ${source.option1} 的翻译不一致`);
      }
      translatedPrimary.set(sourceKey, translatedKey);
      const combinationKey = `${translatedKey}|${originalData.productType === 'two' ? option2.toLocaleLowerCase('vi') : ''}`;
      if (combinations.has(combinationKey)) {
        throw new Error('规格翻译产生重复组合');
      }
      combinations.add(combinationKey);
      return { id: source.id, option1, option2: originalData.productType === 'two' ? option2 : '' };
    });
    variationLabels = { name1, name2: originalData.productType === 'two' ? name2 : '', values };
  }

  return {
    callback_secret: originalData.callbackSecret,
    task_id: originalData.taskId,
    products,
    variation_labels: variationLabels,
    callbackUrl: originalData.callbackUrl,
  };

