const body = $input.first().json.body || {};
  const taskId = String(body.task_id || '').trim();
  const sourceBrief = String(body.source_brief || '').trim();
  const referenceTitle = String(body.reference_title || '').trim();
  const productType = ['single', 'one', 'two'].includes(body.product_type) ? body.product_type : 'one';
  const variationName1 = String(body.variation_name1 || '').trim();
  const variationName2 = String(body.variation_name2 || '').trim();
  const subTasks = Array.isArray(body.sub_tasks) ? body.sub_tasks.map(item => ({
    sub_task_id: String(item?.sub_task_id || '').trim(),
    set_index: Number(item?.set_index) || 0,
  })) : [];
  const variants = productType === 'single' ? [] : (Array.isArray(body.variants) ? body.variants.map(item => ({
    id: String(item?.id || '').trim(),
    option1: String(item?.option1 || '').trim(),
    option2: String(item?.option2 || '').trim(),
  })) : []);
  const callbackSecret = String(body.callback_secret || '');
  const callbackUrl = String(body.callback_url || '').trim();

  if (!taskId || !callbackUrl || !callbackSecret) {
    throw new Error('缺少 task_id、callback_url 或 callback_secret');
  }
  if (sourceBrief.length < 10 || sourceBrief.length > 2000) {
    throw new Error('source_brief 必须为10~2000字符');
  }
  if (!subTasks.length || subTasks.some(item => !item.sub_task_id)) {
    throw new Error('sub_tasks 无效');
  }
  if (Number(body.sub_task_count) !== subTasks.length) {
    throw new Error('sub_task_count 与 sub_tasks 数量不一致');
  }
  if (productType !== 'single' && (!variationName1 || !variants.length)) {
    throw new Error('规格商品缺少一级规格信息');
  }
  if (productType === 'two' && (!variationName2 || variants.some(item => !item.option2))) {
    throw new Error('二维规格信息不完整');
  }
  if (variants.some(item => !item.id || !item.option1)) {
    throw new Error('variants 包含无效记录');
  }

  const outputShape = {
    products: subTasks.map(item => ({
      sub_task_id: item.sub_task_id,
      product_name: '越南语商品标题',
      product_description: '越南语商品描述',
    })),
    variation_labels: productType === 'single' ? { name1: '', name2: '', values: [] } : {
      name1: '越南语一级规格名',
      name2: productType === 'two' ? '越南语二级规格名' : '',
      values: variants.map(item => ({
        id: item.id,
        option1: '越南语一级规格值',
        option2: productType === 'two' ? '越南语二级规格值' : '',
      })),
    },
  };

  const finalPrompt = `
你是 Shopee 越南站商品信息编辑。根据用户确认的商品事实，生成可直接写入官方批量上传模板的商品元数据。

商品事实：
${sourceBrief}

可选参考标题：
${referenceTitle || '无'}

商品规格结构：
${JSON.stringify({
    product_type: productType,
    variation_name1: variationName1,
    variation_name2: variationName2,
    variants,
  }, null, 2)}

输出对象结构：
${JSON.stringify(outputShape, null, 2)}

必须遵守：
1. 只输出一个严格 JSON 对象，不要 Markdown、代码围栏、注释或解释。
2. products 必须严格对应输入的 ${subTasks.length} 个 sub_task_id，不得增删或改写 ID。
3. product_name 使用自然越南语，按“主关键词 + 副关键词 + 长尾词 + 属性词”的语义顺序组织，长度60~110字符，硬限制10~120字符；同批标题不得重复。
4. product_description 使用自然越南语，长度建议300~800字符，硬限制100~3000字符。描述产品类型、已知材质、功能、规格、适用场景、包装或使用注意事项，只能使用商品事实中明确的信息。
5. 禁止虚构品牌、材质、认证、产地、赠品、保修、疗效、销量、价格或夸大承诺；不要写店铺名、联系方式、外链或标签词堆砌。
6. variation_labels 只做规格标签规范化或越南语翻译，不改变含义、不合并组合、不生成营销文案。
7. 规格名长度1~14字符，规格值长度1~20字符。相同原始 option1 在不同组合中必须返回完全相同的 option1。
8. product_type=single 时 variation_labels 必须保持空名称和空 values；product_type=one 时 name2 和每个 option2 必须为空；product_type=two 时两级名称和值都必须填写。
9. variation_labels.values 必须严格保留输入 variants 的 id 和数量。
`;

  return {
    taskId,
    productType,
    subTasks,
    variants,
    finalPrompt,
    callbackSecret,
    callbackUrl,
  };
